<?php
declare(strict_types=1);
namespace Tests\Unit\Infrastructure\Cache;
use App\Domain\Auth\User\UserId;use App\Domain\Posts\Post\Post;use App\Domain\Posts\Post\PostId;use App\Domain\Posts\Post\PostRepository;use App\Infrastructure\Cache\CachedPostRepository;use App\Infrastructure\Cache\RedisCache;use PHPUnit\Framework\TestCase;
final class CachedPostRepositoryTest extends TestCase { public function testLoadsFromInnerThenCacheWithTtl(): void { $post = Post::reconstitute(PostId::fromString('p-1'),UserId::fromString('u-1'),'Title','Body',new \DateTimeImmutable('2026-01-01T00:00:00+00:00')); $inner = new class($post) implements PostRepository { public int $calls=0; public function __construct(private Post $post) {} public function nextId(): PostId { return PostId::fromString('n-1'); } public function byId(PostId $id): ?Post { $this->calls++; return $this->post; } public function save(Post $post): void {} }; $cache = new class extends RedisCache { public array $items=[]; public ?int $ttl=null; public function __construct() {} public function get(string $key): ?string { return $this->items[$key] ?? null; } public function set(string $key, string $value, ?int $ttlSeconds = null): void { $this->items[$key]=$value; $this->ttl=$ttlSeconds; } public function del(string $key): void { unset($this->items[$key]); } }; $repo = new CachedPostRepository($inner,$cache,321); $repo->byId(PostId::fromString('p-1')); $repo->byId(PostId::fromString('p-1')); self::assertSame(1,$inner->calls); self::assertSame(321,$cache->ttl); }}
